#include <stdio.h>
#include <math.h>
#define PI acos(-1.0)
int main(void) {
    double x;
    double data;
    double xAtMax;
    double dataMax = -2.0;
    int numRows;
    int numCols;
    int countRows;
    int countCols;
    printf("Please enter number of rows in table: ");
    scanf("%d", &numRows);
    printf("Please enter number of columns in table (excluding the first): ");
    scanf("%d", &numCols);
    countRows = 1;
    while (countRows <= numRows) {
        x = countRows * PI / numRows;
        printf("%4.3f", x);
        countCols = 1;
        while (countCols <= numCols) {
            data = sin(countCols * x);
            if (data > dataMax) {
                dataMax = data;
                xAtMax = x;
            }
            printf("%8.4f", data);
            countCols++;
        }
        printf("\n");
        countRows++;
    }
    printf("Maximum output value of %.4f occurs at x = %.3f\n", dataMax, xAtMax);
    return 0;
}

#include <stdio.h>
#define INPUTFILE "input.dat"
#define OUTPUTFILE "output.dat"
int main(void) {
    FILE* inFile;
    FILE* outFile;
    double nextVal;
    inFile = fopen(INPUTFILE, "r");
    if (inFile == NULL)
        printf("Error opening input file; program terminating.\n");
    else {
        outFile = fopen(OUTPUTFILE, "w");
        if (outFile == NULL) {
            printf("Error opening output file; program terminating.\n");
            fclose(inFile);
        }
        else {
            while (fscanf(inFile, "%lf", &nextVal) == 1) {
                if (nextVal < 0)
                    fprintf(outFile, "%.2f\n", 0.0);
                else if (nextVal > 1)
                    fprintf(outFile, "%.2f\n", 1.0);
                else
                    fprintf(outFile, "%.2f\n", nextVal);
            }
            fclose(inFile);
            fclose(outFile);
        }
    }
    return 0;
}
